            // novels = novels.filter(novel => {
            //     return !tagsBlockWords.some(item => {
            //         if (novel.tags !== undefined) return novel.tags.includes(item)
            //     })
            // })
            novels = novels.filter(novel => !tagsBlockWords.some(item => novel.tagsList.includes(item)))
