@js:
if (source.getVariable() == "") {
  java.log("未注册设备，自动注册中…");
  eval(String(source.loginUrl));
  login();
}
let push = (list, title, url, type) => list.push({ title: title, url: url, style: { layout_flexGrow: type } });

const categories = [
  [
    "玄幻", "奇幻", "武侠", "仙侠", "都市",
    "历史", "军事", "奇闻怪谈", "科幻", "游戏",
    "体育", "N次元", "现实"
  ],
  [
    "玄幻言情", "仙侠奇缘", "古代言情", "现代言情",
    "浪漫青春", "奇闻怪谈", "科幻空间", "游戏竞技",
    "N次元", "同人纯爱", "短篇"
  ]
];

let list = [];

// 男生推荐
push(list, "▱▱▱▱男生推荐▱▱▱▱", null, 1);
categories[0].forEach(category => {
  // 生成动态请求地址
  let u = `@js:let t = Date.now().toString();
  let params = {
    btype: 100,
    category: "${category}",
    ctype: 1,
    page: page - 1,
    pageSize: "16",
    t: t
  };
  creatRequest("/book_mall/book_rank", params)`;
  push(list, category, u, 0.16);
});

// 女生推荐
push(list, "▱▱▱▱女生推荐▱▱▱▱", null, 1);
categories[1].forEach(category => {
  let u = `@js:let t = Date.now().toString();
  let params = {
    brtype: 100,
    category: "${category}",
    ctype: 2,
    page: page - 1,
    pageSize: "10",
    t: t
  };
  creatRequest("/book_mall/book_rank", params)`;
  push(list, category, u, 0.16);
});

JSON.stringify(list);

